/* @lc app=leetcode id=3649 lang=kotlin */ class Solution { fun ub(a: List<Long>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun perfectPairs(nums: IntArray): Long = nums.map { Math.abs(it.toLong()) }.sorted().let { v -> v.indices.sumOf { i -> (ub(v, 2 * v[i]) - i - 1).toLong() } } }